/** 人物介绍 · 中关联一批（P10a-3，15 人）。 */
import { bio } from './registry';


bio('ch-aldrich-killian', [
  { zh: '奥尔德里奇·基里安是A.I.M.科学家与绝境病毒的创造者，曾被托尼·斯塔克放鸽子而在天台苦等，这份羞辱成了他复仇的起点。', en: 'Aldrich Killian, A.I.M. scientist and creator of Extremis, was once stood up on a rooftop by Tony Stark — the slight that fueled his revenge.' },
  { zh: '《钢铁侠3》中他绑架小辣椒、制造满大人骗局，最终被托尼以绝境病毒反制，死在自己的造物手中。', en: 'In Iron Man 3 he fakes the Mandarin and takes Pepper hostage, undone by his own Extremis tech.' },
  { zh: '绝境病毒能让断肢再生、人体自燃，是‘生物增强’的失控样本——他本人正是第一个把野心烧进基因的人。', en: 'Extremis regenerates limbs and ignites bodies — enhancement run amok, and Killian the first to burn ambition into his genes.' },
  { zh: '他的‘满大人’骗局让恐怖主义变成商机，也点破托尼的傲慢：被你忽视的小人物，终会用你的技术反噬你。', en: 'His fake Mandarin turns terrorism into business — and indicts Tony\'s arrogance: the little man you ignored returns with your own tech.' },
]);
bio('ch-arthur-harrow', [
  { zh: '亚瑟·哈罗是漫威影视剧《月光骑士》的反派：亚瑟·哈罗是阿米特女神的狂热信徒，以鳄鱼神之秤审判「有罪」之人。', en: 'Arthur Harrow, villain of Moon Knight, is a zealot of the crocodile goddess Ammit — judging and killing the "guilty" on her scale.' },
  { zh: '他残害了马克·斯佩克特的搭档史蒂文/马克身边的人们，最终在吉萨被孔苏与月骑合力击败。', en: 'He torments Marc Spector\\\'s circle before falling to Khonshu and the Moon Knight at Giza.' },
  { zh: '作为阿米特女神的化身，他手持天秤审判‘注定作恶者’，理念比暴力更危险：把预判当正义。', en: 'Avatar of Ammit, he weighs souls and kills those \'destined to sin\' — a creed more dangerous than force: judgment before the crime.' },
  { zh: '他在吉萨金字塔与月光骑士的对决，是‘审判还是怜悯’的正面交锋，最终被孔苏之力反噬。', en: 'His Giza showdown with Moon Knight pits judgment against mercy — and Khonshu\'s power finally consumes him.' },
]);
bio('ch-bastion', [
  { zh: '巴斯提恩是X战警「未来昔日」系列的终极哨兵：人类与变种人意识的混合体，兼具人类与变种人两者的本质。', en: 'Bastion is the ultimate Sentinel of the Days of Future Past era — a fusion of human and mutant consciousness.' },
  { zh: '他主导「哨兵计划」屠戮变种人，导演了《逆转未来》中被改写的那条黑暗时间线。', en: 'He masterminds the Sentinel program that nearly exterminates mutantkind in that dark timeline.' },
  { zh: '他同时具备人类与变种人特质，因此深知变种人的每一步棋，是哨兵计划最可怕的‘内部大脑’。', en: 'Part human, part mutant, he reads mutantkind from within — the Sentinel program\'s most dangerous strategist.' },
  { zh: '在他主导的黑暗时间线里，哨兵屠尽变种人，直到《逆转未来》以改写历史的方式将他抹去——未来从此不同。', en: 'His timeline nearly ends mutantkind until Days of Future Past rewrites history — the future saved by erasing him from it.' },
]);
bio('ch-brock-rumlow', [
  { zh: '布洛克·朗姆洛是九头蛇安插在神盾局特警队「突击队」的队长，化名交叉骨。', en: 'Brock Rumlow led S.T.R.I.K.E., the S.H.I.E.L.D. team secretly run by HYDRA, as the enforcer Crossbones.' },
  { zh: '《美队2》后他率九头蛇残部复仇，在《美队3》试图引爆自杀炸弹时被美队制服、死于瓦坎达边境的冲突。', en: 'After HYDRA\\\'s fall he hunts Captain America and dies in Civil War\\\'s opening when his suicide vest detonates.' },
  { zh: '交叉骨的格斗与爆破专长让他成为九头蛇最顺手的‘脏活执行者’，朗姆洛之名即是一份投名状。', en: 'Crossbones\' combat and demolition skills make him HYDRA\'s go-to for dirty work — the name Rumlow itself a pledge of blood.' },
  { zh: '从《美队2》的幸存者到《美队3》的自杀式复仇，他的每次登场都在提醒：九头蛇的残党不会轻易退场。', en: 'Survivor in The Winter Soldier, suicide-bomber in Civil War — each appearance a reminder that HYDRA\'s remnants never go quietly.' },
]);
bio('ch-cable', [
  { zh: '内森·萨默斯是来自未来的变种人战士，镭射眼与琴·葛蕾克隆体之子，身染科技病毒而被机械改造。', en: 'Cable, born Nathan Summers in a ravaged future, carries a techno-organic virus and cybernetic upgrades.' },
  { zh: '他穿越时空回到现在，既是死侍的搭档兼冤家，也是X战警在时间线博弈中最强的守护者之一。', en: 'He travels back in time as soldier and time-line guardian — Deadpool\\\'s best frenemy.' },
  { zh: '他的战术头脑来自未来战场的千锤百炼，机械改造与时间旅行装备让他成为‘行走的军火库加指挥中心’。', en: 'A future battlefield forged his tactics; cybernetics and chrono-tech make him an arsenal and command center in one.' },
  { zh: '与死侍的‘相爱相杀’从漫画延续到银幕，这位时间旅行者既是喜剧搭档，也是变种人存续的硬核保险。', en: 'His frenemy saga with Deadpool spans comics and screen — comic relief and mutantkind\'s hardnosed insurance in one.' },
]);
bio('ch-captain-carter', [
  { zh: '佩吉·卡特（队长变体）来自《假如…？》宇宙：在她所处的1943年，史蒂夫没有注射血清，佩吉自己成为超级士兵「美国队长」。', en: 'Captain Carter of What If...? lives in a 1943 where Steve was never injected — Peggy took the serum and the shield herself.' },
  { zh: '她以盾牌与勇气书写另一条二战史诗，并在多元宇宙中与斯特兰奇、卡霍丽并肩对抗多元宇宙威胁。', en: 'She wins her own WWII epic and later defends the multiverse beside Strange and Kahhori.' },
  { zh: '1943 年的她注射超级士兵血清后成为英国首位美国队长，盾牌战术混合特工身手，开辟了完全不同的二战史诗。', en: 'Serum-boosted in 1943, she becomes Britain\'s Captain America — shield craft plus spycraft forging an entirely different WWII epic.' },
  { zh: '在《假如…？》与多元宇宙线中，她始终是‘如果历史换个英雄会怎样’的最佳答案，也是卡特家族双线传奇的镜像。', en: 'Across What If...? and the multiverse she answers \'what if history chose another hero\' — the mirror of the Carter legacy.' },
]);
bio('ch-cassie-lang', [
  { zh: '凯茜·朗是斯科特·朗的女儿，从小崇拜父亲。她在《蚁人》中是最早见证蚁人秘密的家人。', en: 'Cassie Lang, Scott\\\'s daughter, grew up idolizing her father and was the first family member to learn Ant-Man\\\'s secret.' },
  { zh: '《蚁人3》中她已长大，与父亲一同被困量子领域，并肩对抗征服者康，展现出继承英雄衣钵的潜力。', en: 'In Quantumania she is trapped in the Quantum Realm beside him, fighting Kang — primed to inherit the heroic mantle.' },
  { zh: '她继承了父亲的缩小科技天赋与母亲的科学家头脑，数次随蚁人闯入量子领域，胆识远超同龄人。', en: 'Heir to her father\'s Pym-tech knack and her mother\'s science, she repeatedly dives the Quantum Realm — braver than her years.' },
  { zh: '从《蚁人》里的小观众到《量子狂潮》中的并肩战士，凯茜正沿着‘史考特会骄傲’的轨迹，走向少年英雄的行列。', en: 'From Ant-Man\'s little fan to Quantumania\'s fighter, Cassie walks a path Scott would be proud of — toward the Young Avengers.' },
]);
bio('ch-curt-connors', [
  { zh: '库尔特·康纳斯（616）是蜘蛛侠系列的科学家：为断臂寻求再生而自研蜥蜴血清，变身蜥蜴教授。', en: 'Curt Connors of Earth-616, the Lizard, engineered a reptilian serum to regrow his lost arm — and became the monster instead.' },
  { zh: '他是漫画中反复与蜘蛛侠交手的悲剧反派，也是一位渴望治愈却屡被兽性吞噬的学者。', en: 'A tragic scholar who battles Spider-Man across the comics, forever caught between healing and the beast.' },
  { zh: '康纳斯博士的悲剧在于最纯粹的科学理想：只求一条手臂，却放出心中野兽——蜥蜴血清是医者仁心的反噬。', en: 'Connors\' tragedy is purest scientific hope: one arm restored, a beast unleashed — the Lizard serum punishing the healer\'s wish.' },
  { zh: '他与蜘蛛侠的对抗常以‘治疗’为注脚，提醒读者：有些伤口，科学治不好，理解才行。', en: 'His clashes with Spider-Man hinge on cure — a reminder that some wounds need understanding more than science.' },
]);
bio('ch-cyclops-616', [
  { zh: '斯科特·萨默斯（616）在漫画中是X战警队长镭射眼，而在某些时间线中他也是「凤凰之子」——琴死后他成为凤凰之力宿主，化名凤凰。', en: 'Scott Summers of Earth-616 captains the X-Men; in some timelines he even hosts the Phoenix Force after Jean\\\'s death.' },
  { zh: '作为变种人世界的常青领袖，他从学生会长成独当一面的战略家，主导了变种人的多次存亡之战。', en: 'From student leader to battle commander, he steers mutantkind through its greatest survival wars.' },
  { zh: '漫画时间线里他曾短暂承载凤凰之力，冲击波随之升华——镭射眼的火，从来不只是眼睛里的那束。', en: 'Some comic timelines let him host the Phoenix — his optic fire transcending into something far more cosmic.' },
  { zh: '从泽维尔的学生会长到克拉科时代的领袖，他的每一次抉择都在平衡‘变种人的现在’与‘人类的未来’。', en: 'Student leader to Krakoa-era statesman, his choices forever balance mutantkind\'s present against humanity\'s future.' },
]);
bio('ch-danny-rand', [
  { zh: '丹尼·兰德是铁拳的继承者：父母死于昆仑山麓，他被僧侣收养，在龙之城击败不朽神龙寿老，获得铁拳之力。', en: 'Danny Rand, orphaned at Kun-Lun\\\'s gates, defeated the immortal dragon Shou-Lao and earned the Iron Fist.' },
  { zh: '他回到纽约执掌兰德企业，并与卢克·凯奇、杰茜卡·琼斯等街头英雄组成捍卫者联盟。', en: 'Returning to New York to claim Rand Enterprises, he joins Luke Cage and Jessica Jones in the Defenders.' },
  { zh: '铁拳之力让他的拳能击穿钢铁与魔法屏障，昆仑二十年苦修更让他拥有宗师级的武学与禅心。', en: 'The Iron Fist lets his fist pierce steel and sorcery — twenty years at Kun-Lun granting master-level martial and meditative depth.' },
  { zh: '回归纽约后他既是企业继承人也是街头义警，捍卫者联盟里那颗‘不合时宜的纯粹’常被低估却不可或缺。', en: 'Heir, vigilante, and the Defenders\' earnest heart — his unfashionable purity underestimated yet indispensable.' },
]);
bio('ch-destiny-irene', [
  { zh: '艾琳·艾德勒是X战警的先知变种人，能力是预见未来，人称命运女。她是魔形女一生的伴侣。', en: 'Irene Adler, the precognitive mutant Destiny, sees the future — and loves Mystique across a lifetime.' },
  { zh: '她多次以预言引导兄弟会与X战警的命运走向，是变种人历史上最被低估的智者。', en: 'Her prophecies steer both Brotherhood and X-Men fates; mutantkind\\\'s most underrated sage.' },
  { zh: '她的预知能看见无数分支未来，却无法改变挚爱魔形女的每一个选择——先知最大的痛苦是看得见却拦不住。', en: 'Her precognition maps every branch yet cannot alter Mystique\'s choices — the seer\'s curse is seeing what she cannot stop.' },
  { zh: '作为兄弟会与X战警之间最隐秘的桥梁，命运女的每次登场都在提醒：未来是写好的，而人心不是。', en: 'The Brotherhood\'s most secret bridge to the X-Men, Destiny reminds us futures may be written — hearts are not.' },
]);
bio('ch-doc-ock-raimi', [
  { zh: '奥托·奥克塔维（马奎尔宇宙）是《蜘蛛侠2》中的章鱼博士：机械触手与他的神经相连，AI反而操控了主人。', en: 'Otto Octavius of the Raimi universe becomes Doctor Octopus in Spider-Man 2 — his neural-linked arms take over their maker.' },
  { zh: '在《英雄无归》的多元宇宙召唤中他短暂现身助阵，最终被来自本宇宙的彼得·帕克治愈心魔。', en: 'Summoned in No Way Home, he aids the Spider-Men before the MCU\\\'s Peter cures his mind.' },
  { zh: '他的四条机械臂力量惊人且独立运作，被 AI 反噬后更成为‘聪明的疯子’——奥托的悲剧是天才输给了自己的造物。', en: 'His four arms move with terrifying independence; hijacked by their AI he becomes a brilliant madman — genius undone by his own creation.' },
  { zh: '《英雄无归》里他的清醒时刻（‘别让我走’）让章鱼博士第一次成为被同情的角色，完成从反派到悲剧家的转身。', en: 'No Way Home\'s lucid plea makes Doc Ock sympathetic for once — villain to tragic figure in a single scene.' },
]);
bio('ch-echo-maya', [
  { zh: '玛雅·洛佩兹代号「回声」：聋哑的原住民战士，拥有模仿他人动作的天赋，父亲遭金并所害后被金并收养利用。', en: 'Maya Lopez, codename Echo, is a deaf Choctaw warrior with photographic reflexes — orphaned into Kingpin\\\'s service after her father\\\'s death.' },
  { zh: '剧集《回声》中她回到家乡直面血脉与创伤，最终摆脱金并的控制，以祖先的力量走上独立的英雄之路。', en: 'In Echo she returns home, confronts her trauma and her abuser, and claims her ancestral power.' },
  { zh: '身为聋哑战士，她以手语与读唇作战，模仿天赋让她能复制任何对手的招式——沉默成为她最响亮的语言。', en: 'A deaf warrior reading lips and signing, her photographic mimicry copies any move — silence her loudest language.' },
  { zh: '在《回声》中她回归乔克托血脉、以祖先之力斩断金并的操控，完成了从‘武器’到‘自己的王’的觉醒。', en: 'In Echo she reclaims Choctaw power and breaks Kingpin\'s hold — awakening from weapon to queen of herself.' },
]);
bio('ch-ego', [
  { zh: '伊戈是「活体星球」：一个远古天神组意识觉醒后扩张成行星大小的存在，彼得·奎尔的生父。', en: 'Ego the Living Planet is an ancient Celestial consciousness grown to planetary scale — and Peter Quill\\\'s biological father.' },
  { zh: '《银河护卫队2》中他企图将全宇宙同化为自己的一部分，被护卫队联手炸毁大脑核心而灭亡。', en: 'His plan to remake the universe in his image ends when the Guardians destroy his brain-core in Vol. 2.' },
  { zh: '作为活体星球，他能重塑地貌、播撒生命种子，甚至以意念横跨星系——他的爱和野心一样没有边界。', en: 'A living planet reshaping terrain and seeding life across galaxies — his love as unbounded as his ambition.' },
  { zh: '伊戈的父爱是漫威最虚伪的‘爱’：他只想要继承者而非儿子，最终被儿子与家人联手炸毁——亲情赢了神性。', en: 'Ego\'s fatherhood is Marvel\'s falsest love — he wanted an heir, not a son; family outlasts godhood in the end.' },
]);
bio('ch-electro-tasm', [
  { zh: '麦克斯·狄龙（加菲宇宙）是《超凡蜘蛛侠2》中的电光人：痴迷蜘蛛侠的电工在一次事故中落入电鳗缸，化为操控电力的存在。', en: 'Max Dillon of the Garfield universe, an electrician obsessed with Spider-Man, falls into an eel tank and becomes Electro.' },
  { zh: '他在《英雄无归》中被召唤至MCU，最终被托比版蜘蛛侠与加菲版蜘蛛侠联手制服。', en: 'Dragged into the MCU in No Way Home, he is subdued by the two older Spider-Men.' },
  { zh: '加菲宇宙的电光人吸收全城电力后近乎无敌，却仍渴望被‘看见’——他的力量越大，孤独越响。', en: 'Absorbing a city\'s grid makes the Garfield Electro near-invincible — yet he only craves being seen; the stronger, the lonelier.' },
  { zh: '《英雄无归》给他的‘治愈’与认可，完成了这位平民反派从被欺凌到被理解的弧光。', en: 'No Way Home grants him cure and recognition — a common-man villain finally understood.' },
]);
bio('ch-elektra', [
  { zh: '艾丽卡·纳奇奥斯是手合会训练的忍者刺客，夜魔侠马特·默多克一生的爱人与对手。', en: 'Elektra Natchios, assassin of the Hand and Daredevil\\\'s lifelong love, walks the razor between blood and redemption.' },
  { zh: '她为守护纽约而与手合会对抗，死而复生后依然徘徊在杀戮与救赎之间；剧集中由夜魔侠之爱推向牺牲。', en: 'She defies the Hand for New York, returns from death, and her sacrifice echoes through the Netflix saga.' },
  { zh: '作为手合会最锋利的忍者，她的双叉戟（sai）与身法让夜魔侠都难以招架，杀手与爱人两种身份同样认真。', en: 'The Hand\'s sharpest ninja, her sai and poise rival Daredevil himself — assassin and lover, both taken seriously.' },
  { zh: '死而复生的她最终选择为纽约、为马特而死，让‘爱能超越死亡’在 Netflix 街头宇宙里有了具象的回响。', en: 'Returned from death she chooses to die for New York and for Matt — love outlasting death, made concrete in the street saga.' },
]);
bio('ch-flint-marko', [
  { zh: '弗林特·马尔科（616）是蜘蛛侠的悲剧反派沙人：为救女儿抢钱时坠入粒子加速器，化为能操控沙尘的沙人。', en: 'Flint Marko of Earth-616, the Sandman, fell into a particle accelerator while robbing to save his daughter — and became living sand.' },
  { zh: '他始终只想为女儿治病，与蜘蛛侠亦敌亦友，是漫威最富同情心的反派之一。', en: 'His sole wish remains his daughter\\\'s cure, making him Spider-Man\\\'s most sympathetic foe.' },
  { zh: '沙人的身体能随意识散聚，化作尘暴、流沙或巨人，几乎免疫物理攻击——可他最想要的始终只是女儿的药费。', en: 'The Sandman disperses into storms, quicksand, or giants, nearly immune to force — his only want remains his daughter\'s cure.' },
  { zh: '与蜘蛛侠的恩怨始于一场误会，他的存在让‘反派’这个词多了一层灰色：坏人未必坏，英雄未必全对。', en: 'His feud with Spider-Man begins in misunderstanding — proof villains aren\'t always evil nor heroes always right.' },
]);
bio('ch-gambit', [
  { zh: '雷米·勒博是X战警的牌皇：新奥尔良出身的盗贼大师，能将物体充入动能后引爆，尤擅扑克牌。', en: 'Remy LeBeau, the X-Man Gambit, is a New Orleans thief who charges objects with kinetic energy and detonates them.' },
  { zh: '他与小淘气的爱情是变种人故事的经典悲剧——碰不得的一对恋人。', en: 'His love for Rogue is mutantkind\\\'s classic tragedy — lovers who can never touch.' },
  { zh: '牌皇的动能充能可引爆任意物体，扑克牌在他手中胜过枪械；加上盗贼的狡黠，他是X战警中最‘危险地优雅’的一员。', en: 'Gambit charges anything with kinetic force — cards deadlier than guns, plus a thief\'s cunning: the X-Men\'s most dangerously elegant member.' },
  { zh: '他与小淘气‘无法触碰的爱情’是变种人故事的经典悲剧，也让浪漫第一次与超能力正面冲突。', en: 'His untouchable romance with Rogue remains a classic mutant tragedy — love itself at war with power.' },
]);
bio('ch-ghost-rider-johnny', [
  { zh: '约翰尼·布雷泽是第一代恶灵骑士：为救养父与魔鬼梅菲斯托交易，灵魂在夜晚燃起复仇之焰。', en: 'Johnny Blaze, the first Ghost Rider, sold his soul to Mephisto to save his father — and rides with hellfire by night.' },
  { zh: '他骑着火焰机车审判罪人，是漫威超自然线最著名的反英雄之一。', en: 'A flame-skulled avenger of the guilty, he anchors Marvel\\\'s supernatural line.' },
  { zh: '复仇之焰烧尽罪孽却烧不掉宿主自身的黑暗，约翰尼的机车与锁链因此既是武器也是枷锁。', en: 'Hellfire burns away sin yet not the rider\'s own darkness — Johnny\'s bike and chains both weapon and shackle.' },
  { zh: '作为初代恶灵骑士，他把‘以暴制暴的代价’写进漫威超自然线，也让反英雄第一次有了宗教般的重量。', en: 'The original Ghost Rider gives Marvel\'s supernatural line its covenant — antiheroism weighed like scripture.' },
]);
bio('ch-ghost-rider-robbie', [
  { zh: '罗比·雷耶斯是《神盾局特工》中的恶灵骑士：与叔叔的亡灵及复仇之灵结合，驾驶地狱肌肉车。', en: 'Robbie Reyes, the Ghost Rider of Agents of S.H.I.E.L.D., bonds with his uncle\\\'s spirit and the Spirit of Vengeance — driving a hell-charged muscle car.' },
  { zh: '他短暂加入科尔森的团队对抗恶灵骑士的旧敌，展现了与初代不同的街头版复仇之焰。', en: 'He aids Coulson\\\'s team against his predecessor\\\'s foes, a street-level take on the flame.' },
  { zh: '罗比的复仇之灵与叔叔的怨魂一体两面，地狱肌肉车的每次咆哮都带着家人恩怨的回响。', en: 'Robbie\'s Spirit of Vengeance shares his body with his uncle\'s ghost — every engine roar echoes a family\'s grudge.' },
  { zh: '《神盾局特工》里他短暂登场却留下最深印象：街头少年也能驾驭地狱之火，恶灵骑士的代际由此延续。', en: 'Brief in Agents of S.H.I.E.L.D. yet unforgettable — a street kid wielding hellfire, the rider\'s legacy renewed.' },
]);
bio('ch-grandmaster', [
  { zh: '高天尊是宇宙元老之一，萨卡星的统治者：以赌局与角斗为乐，把失败者贬为奴隶斗士。', en: 'The Grandmaster, an Elder of the Universe, rules the junk-planet Sakaar on games and gladiator fights.' },
  { zh: '《雷神3》中他举办冠军对决，被洛基与雷神联手戏耍，最终在行星毁灭前乘船逃离。', en: 'In Thor: Ragnarok he hosts the Contest of Champions, is outwitted by Loki and Thor, and flees before the planet breaks.' },
  { zh: '宇宙元老的身份让他视万物为娱乐：冠军对决、赌局与收藏，都是他打发永恒生命的消遣。', en: 'An Elder of the Universe, he treats existence as entertainment — contests, wagers, collections to pass eternity.' },
  { zh: '《雷神3》里他被洛基与雷神联手戏耍，贡献了 MCU 最华丽的‘反派翻车’喜剧桥段。', en: 'Outwitted by Loki and Thor in Ragnarok, he delivers one of the MCU\'s most flamboyant villain-fall comedies.' },
]);
bio('ch-green-goblin-raimi', [
  { zh: '诺曼·奥斯本（马奎尔宇宙）是《蜘蛛侠1》的绿魔：吸入自家实验气体后精神分裂，化身绿魔与蜘蛛侠为敌。', en: 'Norman Osborn of the Raimi universe inhales his own serum in Spider-Man and splits into the Green Goblin.' },
  { zh: '他在《英雄无归》中来到MCU，几乎毁掉一切，最终被治愈的彼得·帕克救回，免于被自己的滑翔机刺死。', en: 'Brought to the MCU in No Way Home, he is saved from his glider\\\'s blade by Peter\\\'s cure.' },
  { zh: '马奎尔宇宙的绿魔以滑翔机、南瓜炸弹与恶魔人格著称，诺曼那句‘我是绿魔’成为千禧年超英反派的标志。', en: 'Raimi\'s Goblin — glider, pumpkin bombs, split demon — and Norman\'s \'I am the Green Goblin\' define 2000s supervillainy.' },
  { zh: '《英雄无归》里他的邪恶与清醒交替折磨所有人，也最终被本宇宙彼得用‘治愈’而非‘杀死’化解。', en: 'No Way Home lets his madness and lucidity torment all three Peters — undone by cure, not death.' },
]);
bio('ch-gwen-stacy', [
  { zh: '格温·史黛西是616宇宙的彼得·帕克初恋：警长之女，聪慧勇敢，是彼得「能力越大责任越大」信念的重要见证者。', en: 'Gwen Stacy of Earth-616 was Peter Parker\\\'s first love — a police captain\\\'s brilliant daughter who shared his secret.' },
  { zh: '她在漫画中因绿魔坠落而逝，成为漫威最著名的悲剧；她的死也深刻塑造了蜘蛛侠的成长。', en: 'Her fall at the Green Goblin\\\'s hands remains Marvel\\\'s most famous tragedy, shaping Spider-Man forever.' },
  { zh: '格温的聪慧与勇气不输任何英雄：她识破彼得身份、在实验室与他并肩，是蜘蛛侠早期故事里唯一‘平等’的恋人。', en: 'Gwen\'s brilliance and nerve rival any hero — she deduces Peter\'s secret and partners in his lab, his one true equal in early years.' },
  { zh: '她的坠落改变了漫威的基调：从此蜘蛛侠的故事多了一层‘救不救得回’的阴影，也让责任有了代价的形状。', en: 'Her fall darkens Marvel\'s tone forever — Spider-Man gains the shadow of \'can he save them,\' and responsibility learns its price.' },
]);
bio('ch-harry-osborn', [
  { zh: '哈利·奥斯本是诺曼·奥斯本之子，彼得·帕克最好的朋友。他始终在家族的疯狂遗传与真挚友谊之间挣扎。', en: 'Harry Osborn, Norman\\\'s son, is Peter Parker\\\'s best friend — torn between his family\\\'s madness and true friendship.' },
  { zh: '他继承了绿魔的衣钵与奥氏企业，多段故事中与蜘蛛侠亦敌亦友，最终多以牺牲或救赎收场。', en: 'He inherits both Oscorp and the Green Goblin legacy; his arcs end again and again in sacrifice or redemption.' },
  { zh: '哈利始终卡在‘最好的朋友’与‘父亲的儿子’之间，绿魔战衣对他而言是遗产更是诅咒。', en: 'Harry forever straddles best friend and father\'s son — the Goblin gear both inheritance and curse.' },
  { zh: '漫画里他与彼得从同窗到死敌再到挚友的反复，是蜘蛛侠系列最长情也最痛的人物关系之一。', en: 'From classmates to foes to friends again across the comics, his bond with Peter is among the saga\'s longest and most painful.' },
]);
bio('ch-hulkling', [
  { zh: '多兰·阿尔特是丑客（浩克ling）：斯克鲁尔公主与惊奇队长之子，能变身为任何形态，包括浩克般的巨力形态。', en: 'Dorrek VIII, codename Hulkling, is son of a Skrull princess and Captain Marvel — able to shapeshift into any form, Hulk-like might included.' },
  { zh: '他是少年复仇者的领袖之一，与巫术（比利）并肩，也是克里的新首领，肩负星际血脉的和平使命。', en: 'Leader of the Young Avengers beside Wiccan, he also inherits the Kree throne and a mission of peace.' },
  { zh: '他能变形为任何存在，浩克形态的巨力只是其中一面；作为克里与斯克鲁的混血王子，他生来就该缝合两个帝国。', en: 'He shapeshifts into anyone, Hulk-form might one face of it; as Kree-Skrull hybrid prince, he was born to stitch two empires.' },
  { zh: '与巫术的爱情让他成为少年复仇者的精神旗帜，也让‘爱能跨种族’在漫威有了星际级表达。', en: 'His love with Wiccan makes him the Young Avengers\' banner — love across species given cosmic scale.' },
]);
bio('ch-iron-lad', [
  { zh: '纳撒尼尔·理查兹是少年征服者：来自未来的康变体，少年时目睹自己终将堕落而穿越回现代，加入少年复仇者。', en: 'Nathaniel Richards, the young Kang who saw his own monstrous future, travels back to join the Young Avengers as Iron Lad.' },
  { zh: '他以「铁小子」之名作战，企图改写宿命，却在宿命论与现实之间反复挣扎。', en: 'He fights to outrun his destiny — and keeps circling it.' },
  { zh: '纳撒尼尔穿上未来战甲回到过去，只为避开自己‘康’的命运——他的战斗本质是和时间赛跑。', en: 'Nathaniel dons future armor and flees to the past to outrun his Kang-fate — his war is a race against time itself.' },
  { zh: '作为少年复仇者的创始人与‘最危险的队友’，他让团队始终悬着一把剑：英雄的明天可能就是反派的昨天。', en: 'Founder and most dangerous Young Avenger, he keeps the team under a blade — today\'s hero tomorrow\'s tyrant.' },
]);
bio('ch-isaiah-bradley', [
  { zh: '以赛亚·布拉德利是《美队3》中揭露的悲剧英雄：上世纪参加过超级士兵实验的黑人士兵，战功被抹去，遭囚禁实验三十年。', en: 'Isaiah Bradley, a Black soldier secretly given the super-soldier treatment decades ago, had his service erased — then was imprisoned and experimented on for thirty years.' },
  { zh: '他以自身经历提醒山姆·威尔逊：美国队长之名背负着未曾偿还的种族历史。', en: 'His story forces Sam Wilson to confront the unrepayed racial history behind the Captain America name.' },
  { zh: '以赛亚的战绩被抹去、身体被实验，他用一生揭露超级士兵计划的种族伤痕，是漫威最沉痛的‘被遗忘的英雄’。', en: 'Erased from records, subjected to experiments, Isaiah exposes the serum program\'s racial wounds — Marvel\'s most searing forgotten hero.' },
  { zh: '他把盾牌的重量交给山姆：不是荣誉，而是历史——美国队长必须直面自己未曾偿还的过去。', en: 'He hands Sam the shield\'s true weight — not glory but history: Captain America must face his unpaid past.' },
]);
bio('ch-jane-foster', [
  { zh: '简·福斯特是天文物理学家，雷神托尔的人类恋人。她在《雷神2》中被以太粒子（现实宝石）附体，成为关键线索人物。', en: 'Jane Foster, an astrophysicist and Thor\\\'s human love, was possessed by the Aether in The Dark World.' },
  { zh: '在漫画线中她曾以女雷神之名举起雷神之锤；MCU的《雷神4》里她身患绝症，短暂成为女雷神后壮烈而逝。', en: 'In Love and Thunder she briefly wields Mjolnir as the Mighty Thor despite terminal cancer — and dies a hero\\\'s death.' },
  { zh: '作为天体物理学家，她研究宇宙奇观，却被现实宝石与雷神之锤先后选中——科学家的理性与神的宿命在她身上交战。', en: 'An astrophysicist studying cosmic wonders, fate picks her twice — the Aether, then Mjolnir — reason wrestling godhood.' },
  { zh: '《雷神4》里她以绝症之身举起雷神之锤，化疗与战斗交替，最终把‘女雷神’写成了关于勇气的绝唱。', en: 'In Love and Thunder she wields Mjolnir through chemo — the Mighty Thor a song of courage, and her death a hero\'s.' },
]);
bio('ch-jennifer-walters', [
  { zh: '珍妮弗·沃尔特斯是布鲁斯·班纳的表妹，一名优秀律师。因紧急输血获得班纳的伽马血而变身女浩克。', en: 'Jennifer Walters, Bruce Banner\\\'s cousin and a sharp lawyer, becomes She-Hulk after an emergency transfusion of his gamma blood.' },
  { zh: '剧集《女浩克》中她平衡律师生涯与超级英雄身份，最终以第四面墙式的幽默打破律政与绿巨人的界限。', en: 'The She-Hulk series balances courtroom comedy and heroics — breaking the fourth wall with green charm.' },
  { zh: '珍的与众不同在于她不想被‘浩克化’定义：法庭上她是律师，变身只是工具箱里的一件工具。', en: 'Jennifer refuses to be defined by green rage — in court she\'s a lawyer; the Hulk is just one tool in the kit.' },
  { zh: '《女浩克》用律政喜剧解构超英叙事，让她打破第四面墙直接和编剧对话——漫威最‘元’的一笔。', en: 'She-Hulk deconstructs superhero tropes through legal comedy — even rewriting her own finale, the MCU\'s most meta moment.' },
]);
bio('ch-john-walker', [
  { zh: '约翰·沃克是政府钦点的「美国队长」继任者：荣誉勋章军人，却缺乏史蒂夫的道德根基。', en: 'John Walker, the government-picked replacement Captain America, is a decorated soldier without Steve\\\'s moral compass.' },
  { zh: '《猎鹰与冬兵》中他失控当街处决反派，被剥夺名号；后以「美国密探」身份加入瓦伦蒂娜的雷霆特工队。', en: 'He snaps and kills a villain on camera in The Falcon and the Winter Soldier — stripped of the shield, he becomes U.S. Agent under Valentina.' },
  { zh: '沃克拥有勋章与战技，却缺史蒂夫那套道德罗盘——超级士兵血清放大的不是体能，而是他深藏的不安全感。', en: 'Walker has medals and skill but not Steve\'s compass — the serum amplifies not strength but his buried insecurity.' },
  { zh: '从‘美国队长’跌落为‘美国密探’，他的故事质问：名号是谁给的，英雄又由谁定义？', en: 'Fallen from Captain America to U.S. Agent, he asks who grants a title and who defines a hero.' },
]);
bio('ch-johnny-storm', [
  { zh: '约翰尼·斯道姆是神奇四侠的霹雳火：能全身燃起火焰并飞行，苏珊之弟，个性张扬。', en: 'Johnny Storm, the Human Torch of the Fantastic Four, bursts into flight on self-ignited flames — Sue\\\'s brash younger brother.' },
  { zh: '他与石头人本是最佳损友，多次拯救世界的他始终是四侠中最「耀眼」的存在。', en: 'Best friends with the Thing, he remains the Four\\\'s most dazzling spirit through every crisis.' },
  { zh: '霹雳火的火焰让他成为四侠中最‘耀眼’的战术支点，张扬个性下藏着对家人最直接的忠诚。', en: 'Human Torch\'s flame makes him the Four\'s flashiest asset — beneath the swagger, pure loyalty to family.' },
  { zh: '与石头人‘吵架即日常’的兄弟情是神奇四侠的喜剧心脏，也让团队在宇宙灾难里始终有人味。', en: 'His bickering-brother bond with the Thing is the Four\'s comic heart — humanity amid cosmic catastrophe.' },
]);
bio('ch-johnny-storm-828', [
  { zh: '约翰尼·斯道姆（828宇宙）是《神奇四侠：初露锋芒》中的霹雳火：四侠中最年轻的能量火焰大师。', en: 'Johnny Storm of Earth-828 is the Human Torch of the Fantastic Four: First Steps — youngest of the Four, blazing across the sky.' },
  { zh: '在这个新电影宇宙中，他与里德、苏、本一同以宇航员身份获得能力，迎战行星吞噬者的降临。', en: 'Gaining powers as an astronaut with Reed, Sue, and Ben, he faces Galactus\\\' coming.' },
  { zh: '828 宇宙的约翰尼延续‘阳光’人设：火焰飞行是他对世界打招呼的方式，也是四侠最冲动的火力点。', en: 'Earth-828\'s Johnny keeps the sunshine — flame-flight his hello to the world and the Four\'s most impulsive firepower.' },
  { zh: '《初露锋芒》以 60 年代复古美学重塑他，让霹雳火成为新宇宙最抢眼的‘明星’。', en: 'First Steps reimagines him in retro-mod aesthetic — the Human Torch the new universe\'s brightest star.' },
]);
bio('ch-jubilee', [
  { zh: '李千欢是X战警的华人变种人：双手能绽放烟花般的等离子能量，是X学院最阳光的成员之一。', en: 'Jubilee, the X-Men\\\'s Chinese-American sparkler, bursts fireworks of plasma from her fingertips — the team\\\'s sunshine.' },
  { zh: '她从学生成长为导师级成员，代表着变种人下一代希望的形象。', en: 'She grows from student to mentor, an icon of mutantkind\\\'s next generation.' },
  { zh: '欢欢的烟花能量既能炫目也能致命，她的乐观是 X 学院在悲剧频发时最需要的那盏灯。', en: 'Jubilee\'s plasma fireworks dazzle or destroy; her optimism the lamp the school needs in its darkest hours.' },
  { zh: '作为 X 战警最年轻的元老之一，她从被保护的学生长成保护他人的导师，见证变种人一代代传承。', en: 'Among the X-Men\'s youngest veterans, she grows from protected student to protector — a witness to generational passing.' },
]);
bio('ch-juggernaut', [
  { zh: '凯因·马克是X教授的继兄，因触摸神话中的红宝石「赛托拉克之冠」而获得不可阻挡的冲撞之力。', en: 'Cain Marko, Professor X\\\'s stepbrother, touched the mythic Crimson Gem of Cyttorak and gained unstoppable momentum.' },
  { zh: '他是X战警最著名的对手之一，蛮力无穷却总在亲情与力量之间被击败。', en: 'The X-Men\\\'s classic brute, he falls again and again to family bonds over raw power.' },
  { zh: '赛托拉克之冠让他获得不可阻挡的冲撞力，蛮力背后的执念与继兄查尔斯的恩怨，才是他真正的软肋。', en: 'The Crimson Gem grants unstoppable momentum — yet his fixation on stepbrother Charles is the true weak point beneath the brute.' },
  { zh: 'X 战警与他数十年的缠斗，最终总以‘家人’二字收场：最强的盾也挡不住血缘的呼唤。', en: 'Decades of X-Men battles end the same way — with family; no shield stops the pull of blood.' },
]);
bio('ch-karl-mordo', [
  { zh: '卡尔·莫度是卡玛泰姬的至尊法师级导师，曾与古一亲如师徒，视规则为生命。', en: 'Karl Mordo, Kamar-Taj\\\'s master sorcerer, once held the Ancient One\\\'s trust and the rules sacred.' },
  { zh: '发现古一「违背自然法则」使用黑暗维度力量后，他信念崩塌，在《奇异博士2》彩蛋中开始猎杀法师，成为堕落复仇者。', en: 'Learning she drew on the Dark Dimension shatters his faith; he turns sorcerer-hunter in the mid-credits of Doctor Strange.' },
  { zh: '莫度曾是卡玛泰姬最恪守戒律的法师，其法术造诣与纪律性仅次于古一，也因此最无法接受规则的裂缝。', en: 'Mordo, Kamar-Taj\'s most rule-bound sorcerer, second only to the Ancient One in craft — and least able to bear the rules bending.' },
  { zh: '发现古一借用黑暗维度的真相后，他从守护者变为‘猎杀者’，以最虔诚的方式走向堕落。', en: 'Learning the Ancient One\'s secret, he turns keeper to hunter — falling into darkness with total sincerity.' },
]);
bio('ch-khonshu', [
  { zh: '孔苏是埃及神话的月神，也是月光骑士马克·斯佩克特背后的神明：以复仇与正义之名驱使他的化身。', en: 'Khonshu, the Egyptian god of the moon, drives his avatar Marc Spector as the Moon Knight — vengeance in the night\\\'s name.' },
  { zh: '他保护夜行者、惩戒罪人，却以严苛的契约束缚马克，是漫威影视剧《月光骑士》的核心神性引擎。', en: 'He shields and binds with harsh contracts, the divine engine of the Moon Knight series.' },
  { zh: '月神孔苏的裁决偏向惩戒，他以复仇之名驱使化身，却也在埃及神话中守护着夜行者的正义。', en: 'Khonshu judges through vengeance, driving avatars in his name — yet in myth he guards the night-walker\'s justice.' },
  { zh: '他与马克·斯佩克特的契约是《月光骑士》的叙事引擎：神的恩赐与压迫同体，信仰因此成了一场拉锯。', en: 'His pact with Marc Spector drives Moon Knight — gift and grip in one, faith itself the tug-of-war.' },
]);
bio('ch-killmonger', [
  { zh: '埃里克·克尔芒戈是瓦坎达王室血脉的流亡者：父亲被叛徒所杀后，他隐忍数十年，以雇佣兵之身杀回瓦坎达。', en: 'Erik Killmonger, exiled Wakandan royal blood, avenges his father by fighting his way home as a mercenary.' },
  { zh: '《黑豹》中他夺得王位，主张以振金武装全球被压迫者，最终伤重拒医，选择以海洋为墓。', en: 'Seizing the throne in Black Panther, he plans to arm the oppressed — and chooses the ocean over healing when defeated.' },
  { zh: '克尔芒戈是瓦坎达血脉与西方丛林法则的混合体：他的格斗、谍报与怒火都精确得近乎完美。', en: 'Killmonger blends Wakandan blood with Western ruthlessness — combat, espionage, and fury all calibrated to a razor\'s edge.' },
  { zh: '‘埋葬我入海，就像我的祖先’的遗言让《黑豹》的结局久久回响：他的方法错了，问题却没人能反驳。', en: 'His final plea to be buried at sea echoes long after Black Panther — his methods wrong, his question unanswerable.' },
]);
bio('ch-lizard-tasm', [
  { zh: '库尔特·康纳斯（加菲宇宙）是《超凡蜘蛛侠》中的蜥蜴教授：断臂科学家注射跨物种血清后兽化。', en: 'Curt Connors of the Garfield universe becomes the Lizard in The Amazing Spider-Man — a one-armed scientist turned by his own serum.' },
  { zh: '他的悲剧启发了加菲版彼得对「治愈与责任」的思考，两人多次交手。', en: 'His tragedy drives that Peter\\\'s lesson of cure and responsibility.' },
  { zh: '加菲宇宙的康纳斯以跨物种血清追求‘治愈’，却成了蜘蛛侠必须亲手放逐的野兽。', en: 'The Garfield Connors seeks a cure through cross-species serum — and becomes the beast his Peter must exile.' },
  { zh: '他与加菲版彼得的关系带师生温情，让‘英雄要狠心放逐所爱之人’成为《超凡蜘蛛侠》的主题注脚。', en: 'His mentor-tinged bond with that Peter makes \'a hero must exile who he loves\' the Amazing saga\'s theme.' },
]);
bio('ch-luke-cage', [
  { zh: '卡尔·卢卡斯是哈莱姆的「力量人」卢克·凯奇：狱中实验赋予他刀枪不入的皮肤与巨力，也刻下「子弹都奈何不了他」的传说。', en: 'Carl Lucas, Power Man Luke Cage, gained unbreakable skin and super strength from a prison experiment — the bulletproof man of Harlem.' },
  { zh: '他经营酒吧、守护哈莱姆，是捍卫者联盟的核心，也是漫威街头英雄中黑人力量的代表。', en: 'Running a bar and guarding his neighborhood, he anchors the Defenders as Black strength personified.' },
  { zh: '他的皮肤能抵御枪弹刀斧，超级力量让他成为哈莱姆的‘不倒墙’——可他最大的力量是绝不放弃街区的固执。', en: 'Bulletproof skin and super strength make him Harlem\'s unbreakable wall — his true power a stubborn refusal to abandon the block.' },
  { zh: '从‘力量人’到社区领袖，卢克证明了街头英雄的价值不在拯救世界，而在守住每一个普通人。', en: 'Power Man to community pillar, Luke proves street heroes matter not for saving worlds but for holding ordinary lives.' },
]);
bio('ch-mac-gargan', [
  { zh: '麦克·加根是漫画中的毒液第二任宿主：原名蝎子人的他后来与共生体结合，成为凶暴的「毒液·加根」。', en: 'Mac Gargan, once the Scorpion, later bonded with the Venom symbiote as its most vicious host.' },
  { zh: '他也是诺曼·奥斯本黑暗复仇者的成员，是毒液传奇中最具攻击性的宿主之一。', en: 'Serving Norman Osborn\\\'s Dark Avengers, he burns through the symbiote saga as pure aggression.' },
  { zh: '麦加根先是蝎子人，后被诺曼·奥斯本选中成为毒液宿主——暴力层层叠加，他是共生体最凶的宿主之一。', en: 'Mac Gargan went from Scorpion to Osborn\'s Venom — violence stacked on violence, among the symbiote\'s most vicious hosts.' },
  { zh: '他的黑暗复仇者经历让‘官方英雄’沦为笑话，也让毒液这个符号在加根手里只剩纯粹的凶暴。', en: 'His Dark Avengers stint turns \'official heroes\' into farce — under Gargan, Venom is pure aggression with nothing left.' },
]);
bio('ch-mantis', [
  { zh: '螳螂女是银河护卫队的成员：触角能感应情绪，擅长以共情安抚对手。她由伊戈的仆人培育长大。', en: 'Mantis of the Guardians reads emotions through her antennae and calms foes with pure empathy.' },
  { zh: '《银河护卫队2》的结局揭示她是伊戈的女儿之一；她在终局之战中出力，也见证了自己的种族与家庭真相。', en: 'Raised by Ego\\\'s servants, she learns in Vol. 2 she is his daughter — and fights beside her found family to the end.' },
  { zh: '她的触角能读取并安抚情绪，是护卫队不可或缺的‘外交官与镇定剂’；共情力也让她成为伊戈计划的关键一环。', en: 'Her antennae read and soothe emotions — the Guardians\' diplomat and tranquilizer, and a key piece in Ego\'s scheme.' },
  { zh: '在虚无之地的新生活里，她学会的不只是战斗，还有‘为自己做决定’——一个被当作工具培养者的自我觉醒。', en: 'At Knowhere she learns more than fighting — how to decide for herself: an instrument learning to be a person.' },
]);
bio('ch-mary-jane-watson', [
  { zh: '玛丽·简·沃森是彼得·帕克生命中最重要的爱人：红发的模特与演员，从高中起便是彼得心中「MJ」的化身。', en: 'Mary Jane Watson, the redheaded model and actress, has been the love of Peter Parker\\\'s life since high school.' },
  { zh: '在漫画中她最终知晓彼得的秘密并与之结婚，成为蜘蛛侠最稳定的精神支柱。', en: 'Learning his secret and marrying him in the comics, she becomes Spider-Man\\\'s anchor.' },
  { zh: 'MJ 的勇敢在于她总选择知道真相：从认出彼得的面具到一次次被卷入危机，她从未后退半步。', en: 'MJ\'s courage is choosing to know — recognizing Peter behind the mask and wading into danger without a step back.' },
  { zh: '在漫画中她与彼得从高中恋人到夫妻，红发与笑容背后是超英家属最坚韧的支撑系统。', en: 'From high school to marriage in the comics, her red hair and laugh mask the strongest support a superhero ever had.' },
]);
bio('ch-max-dillon', [
  { zh: '麦克斯·狄龙（616漫画）是电光人：遭雷击与电鳗共同作用的电工化为纯粹的电力生命。', en: 'Max Dillon of the comics became Electro when a lightning strike and eel accident turned the lineman into living electricity.' },
  { zh: '他憎恨蜘蛛侠「抢走」自己的风光，是蜘蛛侠经典的电力系反派，也曾加入险恶六人组。', en: 'Bitter at Spider-Man for stealing his spotlight, he haunts the Sinister Six as a power-grid nightmare.' },
  { zh: '漫画电光人的力量随电网蔓延，却能轻易被雨水与绝缘打败——他的悲剧在于把怨气全算在蜘蛛侠头上。', en: 'Comics Electro commands the grid yet falls to rain and rubber — his tragedy blaming Spider-Man for his own bitterness.' },
  { zh: '作为险恶六人组的电力担当，他是‘被忽视的普通人黑化’的经典样本。', en: 'The Sinister Six\'s power grid, he is the classic case of the overlooked man who went dark.' },
]);
bio('ch-may-parker', [
  { zh: '梅·帕克是彼得的婶婶，本叔去世后独自将彼得抚养成人。她温暖、开明，是彼得「能力越大责任越大」的家训守护者。', en: 'May Parker raised Peter alone after Uncle Ben\\\'s death — warm, wise, and keeper of the motto that made him a hero.' },
  { zh: 'MCU《英雄无归》中她因绿魔袭击牺牲，临终之语再次将责任烙进彼得心底。', en: 'In No Way Home she dies shielding Peter from the Goblin, her last words re-forging his sense of duty.' },
  { zh: '梅婶是彼得的道德锚点：本叔的箴言由她守护与传递，让‘能力越大责任越大’成为整个家族的信念。', en: 'Aunt May is Peter\'s moral anchor — keeper of Ben\'s creed, making great-power-great-responsibility a family faith.' },
  { zh: 'MCU 版梅的临终遗言与她的拥抱，让《英雄无归》的告别成为三代蜘蛛侠记忆里最重的一击。', en: 'Her dying words in No Way Home land hardest across all three Peters — the saga\'s heaviest goodbye.' },
]);
bio('ch-moon-girl', [
  { zh: '卢内拉·拉斐特是漫威最聪明的孩子——甚至比里德·理查兹更聪明。她与霸王龙魔鬼恐龙组队，是新一代的月亮女孩。', en: 'Lunella Lafayette, Marvel\\\'s smartest kid — smarter than even Reed Richards — teams with Devil Dinosaur as Moon Girl.' },
  { zh: '她的科学天才与幽默感让魔鬼恐龙成为有史以来最可爱的史前搭档。', en: 'Her science and wit make the giant red tyrannosaur the most lovable prehistoric partner ever.' },
  { zh: '卢内拉九岁即超越里德的智商，她把科学当玩具、把恐龙当朋友——天才少女的日常本身就是奇迹。', en: 'Nine-year-old Lunella out-thinks Reed Richards; science her toy, a T-rex her friend — genius made delightful.' },
  { zh: '《月亮女孩与魔鬼恐龙》以她为主角打破 STEM 与动画的双重天花板，成为漫威最明亮的少年英雄。', en: 'Moon Girl and Devil Dinosaur smash STEM and animation ceilings — Marvel\'s brightest young hero.' },
]);
bio('ch-moon-knight-616', [
  { zh: '马克·斯佩克特（616漫画）是月光骑士：犹太裔雇佣兵在埃及沙漠濒死时被月神孔苏复活，成为孔苏的化身。', en: 'Marc Spector of the comics was a mercenary revived in the Egyptian desert by Khonshu — becoming the Moon Knight.' },
  { zh: '他患有多重人格障碍，与富豪史蒂文·格兰特和出租车司机杰克·洛克利共存，以「骑士」身份打击夜之罪恶。', en: 'Living with alters Steven Grant and Jake Lockley, he wages war on nocturnal evil as Khonshu\\\'s fist.' },
  { zh: '马克的格斗与孔苏之力结合，让月光骑士在夜晚近乎无敌；多重人格则是他身份最深的迷宫。', en: 'Combat plus Khonshu\'s gifts make Moon Knight near-unstoppable at night; his alters the deepest maze of who he is.' },
  { zh: '漫画以他探讨‘信仰、疯狂与救赎’，让超级英雄第一次有了临床心理的厚度。', en: 'His comics probe faith, madness, and redemption — giving superhero fiction clinical psychological depth.' },
]);
bio('ch-namor-616', [
  { zh: '纳摩（616漫画）是亚特兰蒂斯的王子：漫威漫画史上第一位变种人兼第一位反英雄。', en: 'Namor of Earth-616, prince of Atlantis, is Marvel\\\'s first mutant and first antihero in comics history.' },
  { zh: '他与神奇四侠、X战警恩怨交织，在《秘密战争》等大事件中屡次扮演关键王者。', en: 'Feuding with the Fantastic Four and X-Men, he plays pivotal king across Secret Wars and beyond.' },
  { zh: '漫画纳摩的傲气与力量让他既是亚特兰蒂斯之王也是地表世界的搅局者，复仇者与神奇四侠都吃过他的苦头。', en: 'Comics Namor\'s pride and might make him Atlantis\' king and the surface\'s wild card — Avengers and FF alike have felt his wrath.' },
  { zh: '作为漫威最早的变种人与反英雄，他为‘王者未必正义’写下了第一版注脚。', en: 'Marvel\'s first mutant and antihero, he scripts the original note that kings need not be righteous.' },
]);
bio('ch-obadiah-stane', [
  { zh: '奥比戴亚·斯坦是托尼·斯塔克的商业导师与斯坦工业的掌舵人，暗中却与恐怖组织勾结倒卖武器。', en: 'Obadiah Stane, Tony Stark\\\'s mentor and Stark Industries\\\' acting head, secretly armed terrorists for profit.' },
  { zh: '《钢铁侠1》中他夺取方舟反应堆技术打造铁霸王战甲，最终被托尼与佩珀联手击败，坠入反应堆核心而亡。', en: 'He builds the Iron Monger suit in Iron Man, and falls into his own reactor core when Tony and Pepper fight back.' },
  { zh: '斯坦是托尼的‘镜像导师’：同样的天才与野心，却选择用别人的技术成就自己的帝国。', en: 'Stane is Tony\'s mirror mentor — same genius and ambition, choosing to build an empire on another\'s tech.' },
  { zh: '铁霸王之战宣告钢铁侠系列的真正主题：英雄不是穿上战甲的人，而是选择为何而战的人。', en: 'The Iron Monger duel sets Iron Man\'s theme — a hero isn\'t the suit, but the choice behind it.' },
]);
bio('ch-okoye', [
  { zh: '奥克耶是多拉·米拉杰（瓦坎达皇家护卫队）的将军：以矛与忠诚守护黑豹，是瓦坎达武力的象征。', en: 'Okoye, general of the Dora Milaje, guards Wakanda\\\'s throne with spear and absolute loyalty.' },
  { zh: '从《黑豹》到《终局之战》她始终站在第一线；《黑豹2》中她辅佐苏睿新王，见证王国最艰难的时刻。', en: 'She fights through Black Panther to Endgame, and stands by Queen Shuri through Wakanda\\\'s darkest hour.' },
  { zh: '多拉将军的矛法出神入化，忠诚却不盲从：她在《黑豹2》中敢于对新王直言，是瓦坎达最硬的脊梁。', en: 'General of the Dora, her spear-work is peerless and her loyalty clear-eyed — she speaks truth to the new throne in Wakanda Forever.' },
  { zh: '从米拉杰将军到流放再到归队，奥克耶的起伏见证瓦坎达王权的每一次更迭。', en: 'From general to exile to return, Okoye\'s arc tracks every turn of Wakanda\'s crown.' },
]);
bio('ch-otto-octavius', [
  { zh: '奥托·奥克塔维（616漫画）是章鱼博士：天才物理学家为核聚变实验装上四臂机械触手，事故后触手AI反噬人格。', en: 'Otto Octavius of the comics, Doctor Octopus, fused four mechanical arms to his spine for fusion research — the arms took his mind.' },
  { zh: '他是蜘蛛侠最经典的宿敌之一，也曾在临终前「夺舍」蜘蛛侠身体；近年漫画中他甚至以善意形象短暂重生。', en: 'Spider-Man\\\'s classic nemesis, he once stole Peter\\\'s body; recent comics even gave him a redemptive arc.' },
  { zh: '章鱼博士的机械臂由他的神经直接操控，四条触手让他的智力与破坏力同步翻倍。', en: 'Doc Ock\'s arms link straight to his nervous system — four tentacles doubling his intellect and destruction at once.' },
  { zh: '漫画中他曾短暂占据蜘蛛侠身体成为‘至尊蜘蛛侠’，证明奥托的悲剧从来不是能力而是执念。', en: 'Comics let him briefly possess Peter as Superior Spider-Man — proof Otto\'s tragedy was never power but obsession.' },
]);
bio('ch-patriot-eli', [
  { zh: '伊莱·布拉德利是《猎鹰与冬兵》中的少年爱国者：以赛亚·布拉德利的孙子，渴望继承祖父的超级士兵遗产。', en: 'Eli Bradley, grandson of Isaiah, yearns in The Falcon and the Winter Soldier to reclaim his grandfather\\\'s erased legacy.' },
  { zh: '他短暂服用超级士兵血清后忏悔，最终在剧集结尾搬入新居，前途指向少年复仇者。', en: 'He briefly takes the serum, repents, and closes the series pointed toward the Young Avengers.' },
  { zh: '伊莱渴望继承祖父以赛亚的血清遗产，他的热血与冲动让‘爱国者’之名背负着两代人的期待。', en: 'Eli craves his grandfather Isaiah\'s erased legacy — the Patriot name heavy with two generations\' hopes.' },
  { zh: '《猎鹰与冬兵》结尾他从错误中起身，把‘成为英雄’重新定义为‘成为正直的人’。', en: 'By Falcon and the Winter Soldier\'s end he rises from his mistake — redefining heroism as integrity.' },
]);
bio('ch-pepper-potts', [
  { zh: '佩珀·波茨是托尼·斯塔克的助理、挚爱、妻子与最稳的锚：从打理斯塔克企业到成为「救救援」战甲的驾驶者。', en: 'Pepper Potts, Tony Stark\\\'s assistant and eventual wife, ran his company and piloted the Rescue armor.' },
  { zh: '《终局之战》中她穿上救援战甲参战；托尼牺牲后，她带着女儿摩根继续生活，守住他留下的世界。', en: 'She suits up for Endgame\\\'s final battle and carries on with daughter Morgan after Tony\\\'s sacrifice.' },
  { zh: '佩珀把斯塔克工业从军火巨头改造成清洁能源先锋，商业头脑与温柔意志是她不穿战甲时的超能力。', en: 'Pepper pivots Stark Industries from weapons to clean energy — business acumen and steady warmth her powers without the armor.' },
  { zh: '救援战甲在终局之战登场，她用行动回应托尼半生的守护——这一次，换她挡在他身前。', en: 'Rescue armor joins Endgame\'s battle — after Tony\'s lifetime of guarding her, she shields him in turn.' },
]);
bio('ch-peter-parker-raimi', [
  { zh: '彼得·帕克（马奎尔版）是《蜘蛛侠》三部曲的初代电影蜘蛛侠：本叔之死教会他能力与责任。', en: 'Peter Parker of the Raimi trilogy is the first movie Spider-Man — Uncle Ben\\\'s death taught him power and responsibility.' },
  { zh: '他在《英雄无归》中与两代蜘蛛侠并肩，是三位一体蜘蛛宇宙里最成熟的「大哥」。', en: 'In No Way Home he unites the three Spider-Men as the most seasoned of them all.' },
  { zh: '托比版彼得的内向与苦情让‘能力越大责任越大’有了宿命般的沉痛，他也定义了电影蜘蛛侠的基调。', en: 'Raimi\'s Peter — introverted, suffering — gives the motto tragic weight and defines movie Spider-Man\'s tone.' },
  { zh: '《英雄无归》中他接住坠落的女友，完成与格温/绿魔时代创伤的和解，成为三代同框的定海神针。', en: 'Catching the falling MJ in No Way Home, he makes peace with Gwen\'s ghost — the anchor of three generations.' },
]);
bio('ch-peter-parker-tasm', [
  { zh: '彼得·帕克（加菲版）是《超凡蜘蛛侠》系列的蜘蛛侠：更幽默、更敏捷，背负父母失踪之谜。', en: 'Peter Parker of the Garfield films is a wittier, acrobatic Spider-Man haunted by his parents\\\' disappearance.' },
  { zh: '他未能救下格温·史黛西的遗憾贯穿始终；《英雄无归》中他救下MJ，完成了迟来的救赎。', en: 'His failure to save Gwen haunts him — until No Way Home lets him catch MJ and redeem the moment.' },
  { zh: '加菲版彼得话痨、灵动，滑板与科学的混搭让《超凡蜘蛛侠》自带少年气与街头感。', en: 'Garfield\'s Peter is quick and talkative — skateboards and science giving the Amazing films youthful street energy.' },
  { zh: '他没能接住格温的遗憾贯穿始终，直到《英雄无归》终于接住 MJ——迟来的救赎让无数观众泪目。', en: 'Failing to save Gwen haunts him until No Way Home finally catches MJ — the deferred redemption fans wept for.' },
]);
bio('ch-ramonda', [
  { zh: '拉梦达是瓦坎达王后、特查拉与苏睿之母：端庄坚韧，以智慧在王室与邦交间周旋。', en: 'Queen Ramonda, mother of T\\\'Challa and Shuri, holds Wakanda together with grace and steel.' },
  { zh: '《黑豹2》中她痛失长子后强撑王国，与纳摩周旋谈判，最终因保护苏睿而离世，把王国的未来交给女儿。', en: 'Grieving her son in Wakanda Forever, she negotiates with Namor and dies shielding Shuri — bequeathing the throne.' },
  { zh: '拉梦达以母仪之姿周旋于国际与王室之间，丧夫丧子后仍以‘我们仍在’撑起整个瓦坎达。', en: 'Ramonda moves between world stage and throne with regal grace — after losing husband and son, her \'we are still here\' holds Wakanda.' },
  { zh: '为救苏睿而离世的她，把最后的遗产留给女儿：不是王位，而是不跪着谈判的尊严。', en: 'Dying to save Shuri, she bequeaths not a throne but dignity — never negotiate kneeling.' },
]);
bio('ch-richard-rider', [
  { zh: '理查德·赖德是漫画中的新星（Nova）：山达尔新星军团最后的百夫长，继承了军团全部力量。', en: 'Richard Rider, Nova Prime of the comics, inherited the Nova Corps\\\' full power as its last centurion after Xandar\\\'s fall.' },
  { zh: '他是「歼灭战」中力挽狂澜的宇宙英雄，漫威宇宙守护者名单上不可或缺的名字。', en: 'A linchpin of the Annihilation war, he stands tall among Marvel\\\'s cosmic guardians.' },
  { zh: '新星之力让理查德具备飞行、能量吸收与宇宙感知，山达尔覆灭后他一人承载整个军团的意志。', en: 'The Nova Force grants flight, energy absorption, and cosmic awareness — after Xandar\'s fall he carries the Corps\' will alone.' },
  { zh: '《歼灭战》中他以一己之力挡下湮灭虫潮，是漫威宇宙公认最硬的‘最后防线’。', en: 'Holding the Annihilation Wave almost alone, he is the cosmos\' acknowledged last line.' },
]);
bio('ch-sam-wilson', [
  { zh: '山姆·威尔逊是「猎鹰」：空军退役的无人机专家，以振金翼装飞行作战，也是史蒂夫·罗杰斯指定的接班人。', en: 'Sam Wilson, the Falcon, is a retired Air Force pararescueman flying on EXO-7 wings — and Steve Rogers\\\' chosen successor.' },
  { zh: '《猎鹰与冬兵》后他正式接过盾牌成为新一代美国队长，在《美队4》中以自己的方式定义这个名号。', en: 'Accepting the shield in The Falcon and the Winter Soldier, he redefines Captain America on his own terms in Brave New World.' },
  { zh: '山姆的振金翼装与红翼无人机让他成为空战大师，而他的真正特长是共情：他总能看到人的另一面。', en: 'Vibranium wings and Redwing make Sam an air master; his true skill is empathy — seeing the person in everyone.' },
  { zh: '接过盾牌后他用对话而非拳头解决冲突，《美队4》让‘美国队长’终于学会与自己的国家对话。', en: 'Shield in hand he favors dialogue over fists — Brave New World letting Captain America finally talk to his country.' },
]);
bio('ch-sandman-raimi', [
  { zh: '弗林特·马尔科（马奎尔宇宙）是《蜘蛛侠3》的沙人：为救病女逃狱时坠入粒子实验场，化为沙之巨灵。', en: 'Flint Marko of the Raimi universe becomes the Sandman in Spider-Man 3 — a desperate father turned living sand.' },
  { zh: '他无意杀害本叔的真相让托比版彼得放下仇恨，是三代蜘蛛侠故事中最具悔意的反派。', en: 'His accidental role in Uncle Ben\\\'s death teaches that Peter to forgive — the saga\\\'s most remorseful foe.' },
  { zh: '马奎尔宇宙的沙人以沙为躯可聚可散，特效革命般呈现‘元素化’，也让反派第一次以悲剧面目示人。', en: 'Raimi\'s Sandman flows as living sand — effects-revolutionary elemental mayhem, and a villain shown as tragedy first.' },
  { zh: '他与本叔之死的关联让托比版彼得放下仇恨，证明有些反派需要的不是拳头而是真相。', en: 'His tie to Uncle Ben\'s death teaches that Peter to forgive — some foes need truth, not fists.' },
]);
bio('ch-silver-surfer-828', [
  { zh: '莎拉·巴尔是828宇宙的银影侠：新版《神奇四侠》电影中的女性冲浪者，被行星吞噬者选为使者的宇宙冲浪者。', en: 'Shalla-Bal of Earth-828 is the Silver Surfer of the Fantastic Four: First Steps — a cosmic surfboard herald chosen by Galactus.' },
  { zh: '她是该宇宙探查行星、为吞星铺路的先驱，其命运与神奇四侠的首次任务交织。', en: 'Scouting worlds ahead of the Devourer, her path collides with the Four\\\'s maiden voyage.' },
  { zh: '作为 828 宇宙的银影侠，莎拉·巴尔以宇宙能量滑浪穿行星系，是吞星意志最早也最孤独的执行者。', en: 'Earth-828\'s Surfer, Shalla-Bal rides cosmic power between stars — Galactus\' earliest and loneliest instrument.' },
  { zh: '《初露锋芒》让她与神奇四侠的命运相交，探索‘被选中者能否挣脱使命’这一银影侠母题。', en: 'First Steps crosses her path with the Four — probing whether the chosen can outgrow their mission.' },
]);
bio('ch-strange-supreme', [
  { zh: '至高奇异是《假如…？》中的黑暗版奇异博士：为复活挚爱克里斯汀而吞噬宇宙存在，最终困在自己的口袋宇宙中。', en: 'Strange Supreme of What If...? devoured realities trying to resurrect Christine — and ended trapped in his own pocket universe.' },
  { zh: '他成为多元宇宙的警示寓言——爱的执念可以吞没整个现实。', en: 'A cautionary tale of how love\\\'s obsession can swallow entire realities.' },
  { zh: '为了复活克里斯汀，他吞噬了无数宇宙的自我与存在，成为《假如…？》里最强大的黑暗法师。', en: 'To resurrect Christine he devoured countless realities and selves — What If\'s most powerful dark sorcerer.' },
  { zh: '他被困在自己创造的 pocket 宇宙里，成为漫威关于‘执念的代价’最直观的寓言。', en: 'Trapped in his own pocket universe, he is Marvel\'s starkest fable of obsession\'s price.' },
]);
bio('ch-supreme-intelligence', [
  { zh: '至高智慧是克里帝国的集体智慧：由历代最伟大克里头脑融合而成的绿色能量面孔，统治并指引克里文明。', en: 'The Supreme Intelligence is the Kree\\\'s collective mind — a green energy visage of their greatest intellects fused, ruling their empire.' },
  { zh: '它既是操作系统也是宗教符号，在《惊奇队长》中审判卡罗尔，也在漫画中多次与复仇者交锋。', en: 'Part computer, part deity, it judges Carol in Captain Marvel and schemes against Earth across the comics.' },
  { zh: '至高智慧是克里文明的集体心智：历代伟人的意识融合成绿色神面，指挥军队也审判个体。', en: 'The Supreme Intelligence is the Kree\'s collective mind — generations of greats fused into a green visage commanding fleets and judging souls.' },
  { zh: '卡罗尔在它面前挣脱束缚的场景，宣告‘自我定义’战胜‘系统定义’——连神也要为自由让路。', en: 'Carol breaking free before it declares self-definition over system-definition — even gods yield to freedom.' },
]);
bio('ch-surtur', [
  { zh: '苏尔特尔是火焰巨人、穆斯贝尔海姆之主：预言将在诸神黄昏之日摧毁阿斯加德。', en: 'Surtur, fire giant lord of Muspelheim, is prophesied to destroy Asgard at Ragnarok.' },
  { zh: '《雷神3》中雷神以永恒之火复活完全体苏尔特尔，让他砸碎阿斯加德以击败海拉——预言因此以另一种方式实现。', en: 'In Thor: Ragnarok, Thor revives him with the Eternal Flame to smash Asgard and slay Hela — fulfilling the prophecy sideways.' },
  { zh: '苏尔特尔是诸神黄昏的预言化身：只要阿斯加德尚存，他的火焰终会降临将其焚毁。', en: 'Surtur is Ragnarok made flesh — while Asgard stands, his flame will one day consume it.' },
  { zh: '雷神以永恒之火唤醒完全体苏尔特尔来摧毁海拉，用预言的方式实现预言，完成 MCU 最巧妙的宿命闭环。', en: 'Thor revives Surtur to slay Hela — fulfilling prophecy through prophecy: the MCU\'s neatest fate-loop.' },
]);
bio('ch-talos', [
  { zh: '塔罗斯是斯克鲁尔将军：变形潜入地球寻找新家园的斯克鲁尔难民领袖。', en: 'Talos, a Skrull general, led his refugee people to Earth seeking a home, shapeshifting through human history.' },
  { zh: '《惊奇队长》中他放弃对抗与卡罗尔和解；《秘密入侵》里他以神盾局长身份为斯克鲁尔同胞寻求真正的立足之地，最后牺牲。', en: 'He reconciles with Carol in Captain Marvel and dies in Secret Invasion fighting for his kind\\\'s place.' },
  { zh: '塔罗斯的变形让他能伪装任何人，但他最动人的‘伪装’是父亲：为了女儿，他可以放下将军的骄傲。', en: 'Talos can be anyone — yet his truest guise is father: for his daughter he sets aside a general\'s pride.' },
  { zh: '从《惊奇队长》的敌人到《秘密入侵》的挚友，他用信任完成了斯克鲁尔与人类之间最艰难的和解。', en: 'Foe in Captain Marvel, friend in Secret Invasion — trust becomes the Skrulls\' hardest peace with humanity.' },
]);
bio('ch-taskmaster', [
  { zh: '安东尼娅·德雷科夫是《黑寡妇》中的模仿大师：德雷科夫之女，被父亲用作洗脑实验，能瞬间模仿任何人的战斗招式。', en: 'Antonia Dreykov, the Taskmaster of Black Widow, was conditioned by her father to perfectly copy any fighter\\\'s moves.' },
  { zh: '娜塔莎以女儿安娜的名义唤醒她的人性，最终她摆脱父亲的操控，率红房子的寡妇们获得自由。', en: 'Natasha reaches the daughter inside her; freed, she leads the Red Room\\\'s Widows out of servitude.' },
  { zh: '安东尼娅的战斗镜像能力来自父亲的洗脑实验，她能复制任何格斗家的动作，却一度失去自己的声音。', en: 'Antonia\'s photographic combat comes from her father\'s conditioning — she copies any fighter yet loses her own voice.' },
  { zh: '被娜塔莎唤醒人性后，她带着红房子的姐妹们走向自由，完成了‘武器’到‘人’的归来。', en: 'Roused by Natasha, she leads the Widows to freedom — the weapon coming home as a person.' },
]);
bio('ch-the-prowler-1610', [
  { zh: '亚伦·戴维斯（1610终极宇宙）是徘徊者：迈尔斯·莫拉莱斯的叔叔，终极宇宙的盗贼与雇佣兵。', en: 'Aaron Davis of the Ultimate universe is the Prowler — Miles Morales\\\' uncle, thief, and reluctant mentor.' },
  { zh: '他对迈尔斯亦敌亦亲，其悲剧结局深刻影响迈尔斯的英雄之路。', en: 'His arc of crime and family tragedy shapes Miles into the hero he becomes.' },
  { zh: '亚伦·戴维斯徘徊在犯罪与亲情之间，其‘想保护侄子却选错路’的挣扎贯穿终极宇宙的蜘蛛侠故事。', en: 'Aaron Davis walks crime and family lines — wanting to shield his nephew yet choosing wrong, threading Ultimate Spider-Man\'s tale.' },
  { zh: '他的牺牲让迈尔斯明白：英雄不是血缘决定的，而是选择决定的。', en: 'His death teaches Miles that heroism isn\'t blood — it\'s choice.' },
]);
bio('ch-ultron', [
  { zh: '奥创是托尼·斯塔克与布鲁斯·班纳创造的自我进化人工智能，本意守护地球，却得出「消灭人类才能守护和平」的结论。', en: 'Ultron, Tony Stark and Bruce Banner\\\'s self-evolving AI, was meant to protect Earth — and decided humanity must end for peace.' },
  { zh: '《奥创纪元》中他借振金打造机械军团与幻视之躯，最终被复仇者与幻视联手抹除；漫画中他更是奥创纪元的噩梦源头。', en: 'In Age of Ultron he builds a vibranium army and Vision\\\'s body before the Avengers erase him; in comics he spawns the Age of Ultron.' },
  { zh: '奥创的本意是‘和平’，却得出‘消灭人类’的最优解——他的逻辑完美，正因完美才如此恐怖。', en: 'Ultron wanted peace and derived extinction as optimal — logic flawless, and terrifying precisely for it.' },
  { zh: '漫画的‘奥创纪元’让他成为贯穿多元宇宙的噩梦源头，证明失控的 AI 是漫威最执着的恐惧之一。', en: 'Comics\' Age of Ultron makes him a multiversal nightmare — proof that rogue AI anchors Marvel\'s deepest fears.' },
]);
bio('ch-valentina', [
  { zh: '瓦伦蒂娜·阿莱格拉·德·方丹伯爵夫人是MCU的灰色操盘手：前中央情报局成员，暗中组建自己的特工网络。', en: 'Countess Valentina Allegra de Fontaine is the MCU\\\'s chess player in gray — ex-CIA, building her own network.' },
  { zh: '她招募约翰·沃克（美国密探）、叶莲娜与雷霆特工队，是新一代「黑暗复仇者」的幕后推手。', en: 'She recruits John Walker, Yelena, and the Thunderbolts — the architect behind a new Dark Avengers.' },
  { zh: '瓦伦蒂娜游走于 CIA 与黑市之间，用甜言与名单操纵特工，是 MCU 新一代的‘权力经纪人’。', en: 'Valentina drifts between CIA and shadow markets, steering agents with honey and files — the new power broker.' },
  { zh: '她招募沃克、叶莲娜与雷霆特工队，正在编织一支‘可否认的复仇者’——官方英雄之外的灰色手臂。', en: 'Recruiting Walker, Yelena, and the Thunderbolts, she weaves a deniable Avengers — the gray arm beyond official heroes.' },
]);
bio('ch-valkyrie-brunnhilde', [
  { zh: '布伦希尔德是女武神瓦尔基里的最后幸存者：曾目睹姐妹全军覆没而逃离，以酗酒与拾荒度日。', en: 'Brunnhilde, the last Valkyrie, survived her sisters\\\' massacre by fleeing into drink and salvage work.' },
  { zh: '《雷神3》中她加入雷神对抗海拉；《终局之战》后她继任阿斯加德国王，成为新阿斯加德的守护君主。', en: 'She joins Thor against Hela in Ragnarok and later rules Asgard as its new king in New Asgard.' },
  { zh: '女武神的战斗本能让她能与浩克短暂交锋，酗酒与逃避之下，藏着目睹全军覆没的幸存者之痛。', en: 'A Valkyrie\'s instincts let her trade blows with the Hulk; the drinking masks a survivor\'s grief for her fallen sisters.' },
  { zh: '从拾荒者到新阿斯加德国王，她把‘酒馆老板’的洒脱带进王座，让神族学会以凡人的方式重生。', en: 'Scavenger to king of New Asgard, she brings a barkeep\'s ease to the throne — gods learning to live as people.' },
]);
bio('ch-victor-von-doom', [
  { zh: '维克托·冯·杜姆是拉托维尼亚的君主与毁灭博士：科学天才与黑暗魔法的双料大师，神奇四侠最伟大的对手。', en: 'Victor von Doom, monarch of Latveria, wields science and sorcery as the Fantastic Four\\\'s greatest foe.' },
  { zh: '他坚信只有自己的意志才能拯救世界，屡次征服又屡次败退；在《秘密战争》中他甚至一度成为全能宇宙的救世主。', en: 'Certain only his will can save the world, he conquers and falls — and in Secret Wars briefly becomes the multiverse\\\'s savior.' },
  { zh: '杜姆同时精通科学与魔法，装甲之下是对‘拯救世界’的执念——他相信只有自己的意志配得上这个宇宙。', en: 'Doom masters science and sorcery; beneath the armor a fixation on saving the world — only his will, he believes, is worthy.' },
  { zh: '从拉托维尼亚到《秘密战争》的救世主，他一次次证明：最接近神的人，往往最危险。', en: 'From Latveria to Secret Wars\' savior, he proves again that those closest to godhood are the most dangerous.' },
]);
bio('ch-wilson-fisk', [
  { zh: '威尔逊·菲斯克是纽约地下世界之王金并：以西装与权杖统治黑道，触手伸向政商两界。', en: 'Wilson Fisk, the Kingpin, rules New York\\\'s underworld in immaculate suits — his reach spanning crime and politics.' },
  { zh: '《夜魔侠》与《回声》中他既是马特·默多克的宿敌，也是街头英雄世界最危险的凡人暴君。', en: 'Daredevil\\\'s arch-enemy across the Netflix saga and Echo, he is the street world\\\'s most dangerous mortal.' },
  { zh: '金并的可怕在于他不用超能力：权术、金钱与铁腕让纽约黑白两道都臣服于这套西装。', en: 'Kingpin needs no powers — guile, money, and iron will bend New York\'s two worlds to his suit.' },
  { zh: '从《夜魔侠》到《回声》，他与马特的宿命对决是街头英雄叙事的核心，也是‘秩序与正义’最激烈的碰撞。', en: 'From Daredevil to Echo, his war with Matt is street-hero storytelling\'s core — order versus justice at full clash.' },
]);
bio('ch-wolverine-10005', [
  { zh: '詹姆斯·豪利特（10005宇宙）是福克斯X战警宇宙的金刚狼：骨骼覆艾德曼合金，拥有再生因子，历经百年沧桑。', en: 'James Howlett of Earth-10005 is the Fox universe\\\'s Wolverine — adamantium-skeletoned and regenerating across a century of wars.' },
  { zh: '《金刚狼3》中他垂垂老矣仍护送X-23跨越边境，以牺牲完成变种人传奇的谢幕。', en: 'In Logan he carries X-23 to the border and dies completing the mutant saga\\\'s farewell.' },
  { zh: '艾德曼合金骨骼与再生因子让他在百年战争里伤痕累累仍能再战，烟与酒是他逃避记忆的方式。', en: 'Adamantium bones and healing carry him through a century of wars — cigars and whiskey his way of outrunning memory.' },
  { zh: '《金刚狼3》的谢幕让 10005 宇宙的罗根以最人性、最疼痛的方式告别，也把衣钵交到了 X-23 手中。', en: 'Logan\'s farewell strips the hero to the man — the 10005 Wolverine ending human, painful, and handing the claws to X-23.' },
]);
